<section class="section auth-section"><div class="auth-decoration"><span class="eyebrow">M’S CHARM</span><h2>A little charm.<br>A place of your own.</h2><p>Keep your details close and your favorite pieces closer.</p></div><div class="auth-form"><span class="eyebrow">YOUR ACCOUNT</span><h1><?= e($title) ?></h1><?php if($mode==='register' && welcome_config()['enabled']&&!promo_ready()):$registerOffer=welcome_config(); ?><p class="welcome-register-note">Create your account to receive <?= (int)$registerOffer['percentage'] ?>% off full-priced pieces in your first order, valid for <?= (int)$registerOffer['duration_hours'] ?> hours after registration. New customers only.</p><?php endif ?><form action="/<?= e($mode) ?>" method="post"><?= csrf_field() ?><?php if($mode==='register'): ?><label>Your name<input name="name" required maxlength="120" autocomplete="name"></label><label>Phone (optional)<input name="phone" type="tel" maxlength="40" autocomplete="tel"></label><?php endif ?><label>Email<input name="email" type="email" required maxlength="254" autocomplete="email"></label><label>Password<input name="password" type="password" required <?= $mode==='register'?'minlength="12"':'' ?> maxlength="200" autocomplete="<?= $mode==='register'?'new-password':'current-password' ?>"></label><?php if($mode==='register'): ?><p class="muted">Use at least 12 characters.</p><?php endif ?><button class="button full"><?= $mode==='login'?'Sign in':'Create my account' ?></button></form><p><?= $mode==='login'?'New here?':'Already have an account?' ?> <a class="text-link" href="<?= $mode==='login'?'/register':'/login' ?>"><?= $mode==='login'?'Create an account':'Sign in' ?></a></p></div></section>
